"""Create cited text views of the observed inventory; no downloads or installation."""
import hashlib
import json
from pathlib import Path
import re
import subprocess

HERE = Path(__file__).resolve().parent
data = json.loads((HERE / 'dependency-inventory.json').read_text())
site = Path('/mnt/8t/xubuqiang/anaconda3/lib/python3.12/site-packages')
sections = [(site / 'openpyxl/compat/numbers.py', 1, 45),
            (site / 'openpyxl/xml/__init__.py', 1, 44),
            (site / 'openpyxl/xml/functions.py', 1, 43),
            (site / 'openpyxl/drawing/image.py', 1, 45),
            (site / 'numpy/_distributor_init.py', 1, 60),
            (site / 'mkl/__init__.py', 24, 65),
            (site / 'cffi/api.py', 1, 70),
            (Path('/usr/lib/libreoffice/program/soffice'), 1, 65),
            (Path('/usr/lib/libreoffice/program/soffice'), 160, 200)]
lines = []
for p, start, end in sections:
    lines.append(f'COMMAND: nl -ba {p} | sed -n \'{start},{end}p\'')
    content = p.read_text().splitlines()
    lines.extend(f'{i:6d}\t{content[i-1]}' for i in range(start, min(end, len(content)) + 1))
    lines.append('')
(HERE / 'installed-source-excerpts.txt').write_text('\n'.join(lines) + '\n')

lines = ['Observed inventory generated by: python3 tests/fixtures/hg_spreadrt/summarize.py',
         'Inputs: dependency-inventory.json; see inventory.py for scope/algorithm.',
         'FOUND interpreter: ' + json.dumps(data['python'], sort_keys=True),
         'FOUND openpyxl branch flags: ' + json.dumps(data['openpyxl_flags'], sort_keys=True),
         '', 'FOUND Python distribution metadata (installed versions, not archive equivalence):']
for name, record in data['distributions'].items():
    lines.append(name + ': ' + record['version'] + ' metadata=' + record['metadata_path'])
lines.extend(['', 'FOUND cached Conda artifacts for recorded installed Conda metadata dependency closure.',
              'This closure includes optional/native providers and packaging dependencies; it is an overapproximation.',
              'Current setuptools Python metadata is 82.0.0, while Conda metadata is 69.5.1: DO NOT equate them.',
              'name\tversion\tbuild\tfilename\tobserved_sha256\trecorded_metadata_sha256_match'])
for name, r in data['conda_closure'].items():
    matches = [a for a in data['search']['archives'] if a['path'].endswith('/' + r['fn'])]
    lines.append('\t'.join((name, r['version'], r['build'], r['fn'],
                            matches[0]['sha256'] if matches else 'UNOBSERVED',
                            str(bool(matches and matches[0]['sha256'] == r['sha256'])))))
lines.extend(['', 'FOUND imported-module entry points and observed native extensions:'])
for name in ('openpyxl', 'et_xmlfile', 'numpy', 'numpy.core._multiarray_umath', 'mkl',
             'mkl._mklinit', 'mkl._py_mkl_service', 'cffi', 'PIL', 'PIL._imaging',
             'lxml.etree', 'defusedxml', 'uno'):
    lines.append(name + ': ' + json.dumps(data['modules'].get(name, {'state': 'UNKNOWN/not captured'}), sort_keys=True))
lines.extend(['', 'Exact local executable commands and output:'])
lines.extend(json.dumps(c, sort_keys=True) for c in data['commands'])
lines.extend(['', 'Enumerated search roots and file counts:'])
lines.append(json.dumps(data['search']['visited_files'], sort_keys=True))
lines.append('UNKNOWN scopes/errors: ' + json.dumps(data['search']['errors'], sort_keys=True))
lines.append('FOUND engine candidates: ' + json.dumps(data['search']['engine_candidates'], sort_keys=True))
lines.append('FOUND bridge candidates: ' + json.dumps(data['search']['uno_candidates'], sort_keys=True))
lines.append('FOUND source hashes: ' + json.dumps(data['source'], sort_keys=True))
(HERE / 'dependency-summary.txt').write_text('\n'.join(lines) + '\n')

paths = set()
for command in data['commands']:
    if command.get('argv', [''])[0] == 'ldd':
        paths.update(re.findall(r'(?:=> )?(/[^\s]+) \(', command['stdout']))
for p in Path('/usr/lib/libreoffice').rglob('*'):
    if p.is_file():
        paths.add(str(p))
lines = ['COMMAND: python3 tests/fixtures/hg_spreadrt/summarize.py',
         'Scope: all regular-file paths under /usr/lib/libreoffice (symlinks resolved when hashing)',
         'plus installed library paths resolved by the two exact ldd commands in dependency-inventory.json.',
         'Format: sha256 bytes path; hashes describe installed bytes, not original OS package archives.']
for p in sorted(paths):
    path = Path(p)
    h = hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda: stream.read(1048576), b''):
            h.update(block)
    lines.append(f'{h.hexdigest()} {path.stat().st_size} {p}')
(HERE / 'engine-installed-sha256.txt').write_text('\n'.join(lines) + '\n')
print('dependency_summary=tests/fixtures/hg_spreadrt/dependency-summary.txt')
print('installed_source_excerpts=tests/fixtures/hg_spreadrt/installed-source-excerpts.txt')
print('engine_installed_files_hashed=' + str(len(paths)))
print('all_conda_closure_archives_found=' + str(all(
    any(a['path'].endswith('/' + r['fn']) for a in data['search']['archives'])
    for r in data['conda_closure'].values())))
